// The rating has to be a number the customer actually chose, not one parsed out of prose.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const s = (v) => (v === null || v === undefined ? null : String(v).trim() || null);
  let rating = null;
  if (j.rating !== null && j.rating !== undefined && String(j.rating).trim() !== '') {
    const n = Number(j.rating);
    // Non-integers and out-of-range values are rejected rather than clamped: "10/10" meaning
    // ten stars out of five is a misunderstanding, and storing 5 would be inventing an answer.
    rating = Number.isInteger(n) ? n : NaN;
  }
  const hint = ['praise', 'complaint', 'neutral'].indexOf(s(j.sentiment)) >= 0 ? s(j.sentiment) : 'neutral';
  out.push({ json: {
    booking_ref: s(j.booking_ref),
    rating: rating === null ? null : rating,
    comment: (s(j.comment) || '').slice(0, 2000),      // bounded, never truncated mid-decision
    hint, user_key: s(j.user_key),
    invalid: (!s(j.booking_ref) || !s(j.user_key)) ? 'invalid_input'
             : (rating !== null && !Number.isInteger(rating)) ? 'invalid_rating' : null,
  } });
}
if (out.length === 0) out.push({ json: { booking_ref: null, invalid: 'invalid_input' } });
return out;

// Two replies racing into one appointment's review: the UNIQUE is doing exactly its job,
// so report it as 'already reviewed', not as the database being down.
function dbReason(errText) {
  const e = String(errText || '');
  if (e.includes('review_once_per_appointment')) return 'already_reviewed';
  if (e.includes('appointment_no_double_booking')) return 'slot_taken';
  if (e.includes('statement timeout') || e.includes('canceling statement')) return 'timeout';
  return 'db_unavailable';
}

// A closed contract, and the manager notice as a second item when one is warranted.
const checked = $('Validate input').all();
const out = [];
const rows = $input.all();
for (let i = 0; i < rows.length; i++) {
  const v = (checked[i] || checked[0] || {}).json || {};
  const row = (rows[i] || {}).json || {};
  if (v.invalid)  { out.push({ json: { ok: false, reason: v.invalid } }); continue; }
  if (row.error !== undefined || !row.result) { out.push({ json: { ok: false, reason: dbReason(row.error) } }); continue; }
  const d = row.result;
  if (!d.found)             { out.push({ json: { ok: false, reason: 'booking_not_found' } }); continue; }
  if (d.status !== 'completed') { out.push({ json: { ok: false, reason: 'not_completed' } }); continue; }
  if (!d.rating_ok)         { out.push({ json: { ok: false, reason: 'invalid_rating' } }); continue; }
  if (!d.has_content)       { out.push({ json: { ok: false, reason: 'empty_review' } }); continue; }
  if (d.already_reviewed)   { out.push({ json: { ok: false, reason: 'already_reviewed' } }); continue; }
  if (!d.stored || !d.review) { out.push({ json: { ok: false, reason: 'not_stored' } }); continue; }
  const r = d.review;
  out.push({ json: { ok: true, data: { sentiment: r.sentiment, rating: r.rating, ref: r.ref,
                                       stylist_name: r.stylist_name },
    // Praise AND complaints both reach the manager: you cannot coach a team on complaints alone.
    _notice: r.sentiment === 'neutral' ? null : {
      appointment_id: r.appointment_id, recipient: 'manager',
      kind: 'review_' + r.sentiment,
      text: `${r.sentiment === 'praise' ? 'Praise' : 'Complaint'} for ${r.stylist_name} — `
          + `${r.service_name} on ${r.when_local} (${r.ref}), ${r.rating === null ? 'no rating' : r.rating + '/5'} `
          + `from ${r.client_name}:\n"${r.comment || '(no comment left)'}"` } } });
}
if (out.length === 0) out.push({ json: { ok: false, reason: 'invalid_input' } });
return out;

// Only the reviews that warrant a human become items for the sender.
return $('Respond').all()
  .filter(i => ((i.json || {}).data) && (i.json._notice))
  .map(i => ({ json: i.json._notice }));

// The verdict is what the caller gets back; whether the manager's copy went out is an
// operational detail that must never change what the customer is told.
return $('Respond').all().map(i => {
  const j = i.json || {};
  return { json: j.ok ? { ok: true, data: j.data } : { ok: false, reason: j.reason } };
});
